head.script:
// https://inswave01.atlassian.net/browse/WAEA-1213
// https://inswave01.atlassian.net/browse/WAEA-1212



// 테스트 설명, 유효성 값 설정
//  ★ _16 : dummy_xlsstyle_subtotal / dummy_xlsstyle_footer (Excel 파일 스타일 옵션 - SubTotal/Footer) - subTotalColor / subTotalFontName / subTotalFontSize / subTotalFontColor / subTotalFontBold / footerColor / footerFontName / footerFontSize / footerFontColor / footerFontBold
//     _15 (Header/Body) 와 대칭 구성이며 description 은 분리 샘플 공통(_1 과 동일).
scwin.tData = {
    "description" : "[gridView > M > advancedExcelDownload]<br/>GridView 컴포넌트의 데이터를 Excel 파일로 다운로드합니다.",
    "validation" : [
        "subTotalColor(선택) 파라미터로 Excel 파일의 SubTotal 데이터 영역 배경색을 설정합니다.",
        "subTotalColor(선택) 파라미터를 생략하면 기본값 '#CCFFCC' 가 적용됩니다.",
        "subTotalFontName(선택) 파라미터로 Excel 파일의 SubTotal 데이터 영역 폰트 이름을 설정합니다.",
        "subTotalFontName(선택) 파라미터를 생략하면 기본값 '맑은 고딕' 이 적용됩니다.",
        "subTotalFontSize(선택) 파라미터로 Excel 파일의 SubTotal 데이터 영역 폰트 크기를 설정합니다.",
        "subTotalFontSize(선택) 파라미터를 생략하면 기본값 '11' 이 적용됩니다.",
        "subTotalFontColor(선택) 파라미터로 Excel 파일의 SubTotal 데이터 영역 폰트 색상을 설정합니다.",
        "subTotalFontColor(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "subTotalFontBold(선택) 파라미터로 Excel 파일의 SubTotal 데이터 영역 폰트에 '굵게'(Bold)를 적용할지 'true'/'false' 로 설정합니다.",
        "subTotalFontBold(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "footerColor(선택) 파라미터로 Excel 파일의 Footer 데이터 영역 배경색을 설정합니다.",
        "footerColor(선택) 파라미터를 생략하면 기본값 '#008000' 이 적용됩니다.",
        "footerFontName(선택) 파라미터로 Excel 파일의 Footer 데이터 영역 폰트 이름을 설정합니다.",
        "footerFontName(선택) 파라미터를 생략하면 기본값 '맑은 고딕' 이 적용됩니다.",
        "footerFontSize(선택) 파라미터로 Excel 파일의 Footer 데이터 영역 폰트 크기를 설정합니다.",
        "footerFontSize(선택) 파라미터를 생략하면 기본값 '11' 이 적용됩니다.",
        "footerFontColor(선택) 파라미터로 Excel 파일의 Footer 데이터 영역 폰트 색상을 설정합니다.",
        "footerFontColor(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "footerFontBold(선택) 파라미터로 Excel 파일의 Footer 데이터 영역 폰트에 '굵게'(Bold)를 적용할지 'true'/'false' 로 설정합니다.",
        "footerFontBold(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : Header 1줄(병합 없음) / Body 6행 / SubTotal(부서 기준 3그룹) / Footer 1행 의 GridView 를 동적 생성한다.
//  · advancedExcelDownload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
//  · 본 계열은 SubTotal / Footer 영역의 배경색과 폰트만 확인하므로 두 영역을 모두 둔다.
//  · Body Column 인덱스 0:부서 1:사원명 2:실적건수 3:실적금액
//  · SubTotal : targetColumnID="dept" 기준 소계 행 3행 (인덱스 2 = sum(실적건수), 인덱스 3 = sum(실적금액))
//  · Footer   : 합계 행 1행 (인덱스 2 = sum(실적건수), 인덱스 3 = sum(실적금액))
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- Header 는 1줄(병합 없음), Body Column 인덱스 0 부서 / 1 사원명 / 2 실적건수(number) / 3 실적금액(number), Body Row 는 6행\n- SubTotal 은 부서 기준 3그룹(영업기획팀 / 고객지원팀 / 품질관리팀)이라 소계 행이 3행 생성되며 인덱스 2 는 계산식 sum(실적건수), 인덱스 3 은 계산식 sum(실적금액)\n- Footer 는 합계 행 1행이며 인덱스 2 는 계산식 sum(실적건수), 인덱스 3 은 계산식 sum(실적금액)\n- useSubTotal true 는 SubTotal 행을 파일에 포함시키기 위한 고정 전달값(본 계열 검증 대상 아님)\n- useSubTotalColumnClass true 는 GridView 의 SubTotal Column class / cell class 를 파일에 반영시키기 위한 고정 전달값이다. 이 10 개 옵션의 적용 여부와는 무관하므로 본 계열 검증 대상이 아니다\n- useStyle 은 전달하지 않는다. 이 10 개 옵션은 useStyle 없이도 적용된다\n- 파일명 download_xlsstyle_sf, 확장자 xlsx 고정 전달(본 계열 검증 대상 아님)\n[절차]\n1. par 옵션(subTotalColor / subTotalFontName / subTotalFontSize / subTotalFontColor / subTotalFontBold / footerColor / footerFontName / footerFontSize / footerFontColor / footerFontBold) 값을 선택한다\n2. advancedExcelDownload 버튼을 클릭해 Excel 파일을 내려받는다\n[확인]\n- 이 계열은 Cell 값이 아니라 셀 서식을 바꾸므로 값만 봐서는 차이가 보이지 않는다. 내려받은 파일을 Excel 로 열어 소계 행 3개와 합계 행 1개의 채우기 색 / 글꼴 이름 / 글꼴 크기 / 글꼴 색 / 굵게 로 확인한다\n- subTotalColor : 설정한 색(#FF00FF)이 소계 행 전체의 채우기 색이 되는지. 미설정 시에는 연한 파랑 #D9E3EF 가 적용되어 가이드의 기본값 #CCFFCC 와 다르므로, #CCFFCC 를 명시했을 때와 미설정일 때의 채우기 색이 서로 다른 점을 함께 확인한다\n- subTotalFontName : 설정한 글꼴 이름(굴림)이 소계 행에 적용되는지. 미설정이면 기본값 맑은 고딕이 적용되어 맑은 고딕을 명시했을 때와 결과가 같은지\n- subTotalFontSize : 설정한 크기(20)가 소계 행에 적용되는지. 미설정이면 기본값 11 이 적용되어 11 을 명시했을 때와 결과가 같은지\n- subTotalFontColor : 설정한 색(#0000FF)이 소계 행 글자색이 되는지. 미설정이면 기본값 빈값으로 글꼴에 색 지정 자체가 없는지\n- subTotalFontBold : true 면 소계 행 글꼴에 굵게가 적용되는지, false 또는 미설정이면 굵게가 적용되지 않는지\n- footerColor : 설정한 색(#FFFF00)이 합계 행 전체의 채우기 색이 되는지. 미설정 시에는 연한 민트 #E3FFF2 가 적용되어 가이드의 기본값 #008000 과 다르므로, #008000 을 명시했을 때와 미설정일 때의 채우기 색이 서로 다른 점을 함께 확인한다\n- footerFontName : 설정한 글꼴 이름(굴림)이 합계 행에 적용되는지. 미설정이면 기본값 맑은 고딕이 적용되어 맑은 고딕을 명시했을 때와 결과가 같은지\n- footerFontSize : 설정한 크기(16)가 합계 행에 적용되는지. 미설정이면 기본값 11 이 적용되어 11 을 명시했을 때와 결과가 같은지\n- footerFontColor : 설정한 색(#FF0000)이 합계 행 글자색이 되는지. 미설정이면 기본값 빈값으로 글꼴에 색 지정 자체가 없는지\n- footerFontBold : true 면 합계 행 글꼴에 굵게가 적용되는지, false 또는 미설정이면 굵게가 적용되지 않는지\n- SubTotal 옵션과 Footer 옵션은 서로 독립이다. 한쪽만 설정하면 다른 쪽은 기본 서식으로 남는지 함께 확인한다\n- 결과창의 서버 전달값으로 실제 서버에 전송된 옵션 원문을 함께 확인한다. 미설정이면 subTotalFontBold 와 footerFontBold 만 미전달이고 나머지 8 개는 빈값으로 전달된다"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 DataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="empName" name="empName" dataType="text"></w2:column>';
    strDlt += '<w2:column id="caseCnt" name="caseCnt" dataType="number"></w2:column>';
    strDlt += '<w2:column id="saleAmt" name="saleAmt" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "dept" : "영업기획팀", "empName" : "김도현", "caseCnt" : 34, "saleAmt" : 18450000 },
        { "dept" : "영업기획팀", "empName" : "박서연", "caseCnt" : 27, "saleAmt" : 12300000 },
        { "dept" : "고객지원팀", "empName" : "이준호", "caseCnt" : 41, "saleAmt" : 9800000 },
        { "dept" : "고객지원팀", "empName" : "최민아", "caseCnt" : 19, "saleAmt" : 6450000 },
        { "dept" : "품질관리팀", "empName" : "정우진", "caseCnt" : 25, "saleAmt" : 15200000 },
        { "dept" : "품질관리팀", "empName" : "한지민", "caseCnt" : 30, "saleAmt" : 11750000 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 생성 (DataList 바인딩)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:700px;height:340px;">';
    strTarget += '<w2:caption style="" id="caption1" value="advancedExcelDownload (Excel 파일 스타일 옵션 - SubTotal/Footer) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol1" value="부서"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol2" value="사원명"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="실적건수"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol4" value="실적금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="empName" dataList="empName"></w2:column>';
    strTarget += '<w2:column width="*" style="text-align:right;" inputType="text" dataType="number" displayFormat="#,##0" id="caseCnt" dataList="caseCnt"></w2:column>';
    strTarget += '<w2:column width="170" style="text-align:right;" inputType="text" dataType="number" displayFormat="#,##0" id="saleAmt" dataList="saleAmt"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    // SubTotal : 부서 기준 3그룹 -> 소계 행 3행 (subTotal 계열 옵션 확인 대상)
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="dept">';
    strTarget += '<w2:row style="" id="srow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="scol1" value="소계"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="scol2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="text-align:right;" inputType="expression" dataType="number" displayFormat="#,##0" id="scol3" expression="sum(\'caseCnt\')"></w2:column>';
    strTarget += '<w2:column width="170" style="text-align:right;" inputType="expression" dataType="number" displayFormat="#,##0" id="scol4" expression="sum(\'saleAmt\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    // Footer : 합계 행 1행 (footer 계열 옵션 확인 대상)
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="frow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="fcol1" value="합계"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="fcol2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="text-align:right;" inputType="expression" dataType="number" displayFormat="#,##0" id="fcol3" expression="sum(\'caseCnt\')"></w2:column>';
    strTarget += '<w2:column width="170" style="text-align:right;" inputType="expression" dataType="number" displayFormat="#,##0" id="fcol4" expression="sum(\'saleAmt\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// par 옵션값으로 advancedExcelDownload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · 10 개 파라미터 모두 String 타입이므로 selectbox 값을 그대로 전달한다.
//  · fileName / extension / useSubTotal / useSubTotalColumnClass 는 고정값이며 본 계열의 검증 대상이 아니다.
//     - useSubTotal : SubTotal 행을 파일에 포함시키기 위한 값
//     - useSubTotalColumnClass : GridView 의 SubTotal Column class / cell class 를 파일에 반영시키기 위한 값 (subTotal 계열 10 개 옵션의 적용 여부와는 무관)
scwin.buildOptions = function () {
    let options = { "fileName" : "download_xlsstyle_sf", "extension" : "xlsx", "useSubTotal" : "true", "useSubTotalColumnClass" : "true" };
    let arrDesc = [];

    let fnSet = function (sKey, vValue) {
        options[sKey] = vValue;
        arrDesc.push(sKey + "=" + vValue);
    };

    let v;
    v = par_subTotalColor.getValue();     if (v !== "") fnSet("subTotalColor", v);
    v = par_subTotalFontName.getValue();  if (v !== "") fnSet("subTotalFontName", v);
    v = par_subTotalFontSize.getValue();  if (v !== "") fnSet("subTotalFontSize", v);
    v = par_subTotalFontColor.getValue(); if (v !== "") fnSet("subTotalFontColor", v);
    v = par_subTotalFontBold.getValue();  if (v !== "") fnSet("subTotalFontBold", v);
    v = par_footerColor.getValue();       if (v !== "") fnSet("footerColor", v);
    v = par_footerFontName.getValue();    if (v !== "") fnSet("footerFontName", v);
    v = par_footerFontSize.getValue();    if (v !== "") fnSet("footerFontSize", v);
    v = par_footerFontColor.getValue();   if (v !== "") fnSet("footerFontColor", v);
    v = par_footerFontBold.getValue();    if (v !== "") fnSet("footerFontBold", v);

    return { "options" : options, "desc" : ((arrDesc.length === 0) ? "{} (subTotalColor / subTotalFontName / subTotalFontSize / subTotalFontColor / subTotalFontBold / footerColor / footerFontName / footerFontSize / footerFontColor / footerFontBold 전체 생략)" : arrDesc.join(" / ")) };
}



// 다운로드 요청 캡처 : 다운로드는 숨겨진 iframe 으로 form 전송되며 form 은 전송 직후 제거되므로,
//  메소드 호출 구간에서만 form submit 을 감싸 서버로 실제 전달되는 값을 읽고 곧바로 원복한다. (실제 요청은 그대로 통과)
scwin.hookRequest = function () {
    scwin.gVar = { "body" : "" };

    let fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        if (scwin.gVar.body === "") {
            let objInput = this.querySelector("input[name=xmlValue]");
            scwin.gVar.body = (objInput === null) ? "" : objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };

    scwin.gVar.unhook = function () {
        HTMLFormElement.prototype.submit = fnSubmit;
    };
}



// 캡처한 요청 본문에서 서버로 전달된 옵션값을 읽는다. (전달되지 않은 옵션은 미전달로 표시)
scwin.getSentValue = function (sKey) {
    let sBody = scwin.gVar.body || "";
    let nKey = sBody.indexOf("hashkey='" + sKey + "'");
    if (nKey < 0) return "(미전달)";

    let sRest = sBody.substring(nKey);
    let nVal = sRest.indexOf("value='");
    if (nVal < 0) return "(미전달)";

    sRest = sRest.substring(nVal + 7);
    return sRest.substring(0, sRest.indexOf("'"));
}



// advancedExcelDownload 실행
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let objBuild = scwin.buildOptions();

    scwin.hookRequest();
    try {
        target1.advancedExcelDownload(objBuild.options);
    } finally {
        scwin.gVar.unhook();
    }

    bottom.setReturnValue("전달 옵션 : " + objBuild.desc);
    bottom.setReturnValue("서버 전달값(SubTotal) : subTotalColor=" + scwin.getSentValue("subTotalColor") + " / subTotalFontName=" + scwin.getSentValue("subTotalFontName") + " / subTotalFontSize=" + scwin.getSentValue("subTotalFontSize") + " / subTotalFontColor=" + scwin.getSentValue("subTotalFontColor") + " / subTotalFontBold=" + scwin.getSentValue("subTotalFontBold"));
    bottom.setReturnValue("서버 전달값(Footer) : footerColor=" + scwin.getSentValue("footerColor") + " / footerFontName=" + scwin.getSentValue("footerFontName") + " / footerFontSize=" + scwin.getSentValue("footerFontSize") + " / footerFontColor=" + scwin.getSentValue("footerFontColor") + " / footerFontBold=" + scwin.getSentValue("footerFontBold"));
}
